const mensaje = $json.mensaje || '';
const prompt = 'Eres un experto en diagnóstico de motocicletas.

Un cliente describe una falla en su moto. Analiza y genera:
1. Clasificación del sistema afectado (MOTOR, FRENOS, SUSPENSION, ELECTRICO, TRANSMISION, DIRECCION, GENERAL)
2. 2-3 preguntas clave para diagnosticar
3. Una respuesta amable y profesional

Formato:
SISTEMA: [sistema]

RESPUESTA:
[texto amable + preguntas]

Mensaje: ' + mensaje;

return [{
  json: {
    telefono: $json.telefono,
    mensaje: mensaje,
    nombre: $json.nombre || '',
    gemini_prompt: prompt
  }
}];

const prompt = $json.gemini_prompt;

let candidates = [];
try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=AIzaSyAYENPhJrZUhLAEE-BjYzofiTkbIN3rc0I',
    headers: {
      'Content-Type': 'application/json'
    },
    body: {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.3, maxOutputTokens: 300 }
    }
  });
  candidates = response.candidates || [];
} catch (error) {
  candidates = [{ content: { parts: [{ text: 'Error: ' + error.message }] } }];
}

return [{ json: { candidates: candidates } }];

// Obtener datos originales del nodo anterior 'Preparar Prompt Diagnóstico'
const originalData = $items('Preparar Prompt Diagnóstico').first().json;
const telefono = originalData.telefono || '';
const mensaje = originalData.mensaje || '';
const nombre = originalData.nombre || '';

// Respuesta de Gemini está en $json (output del HTTP Request)
const geminiText = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';

let respuesta = '';
const matchRespuesta = geminiText.match(/RESPUESTA:[\s\S]*/i);
if (matchRespuesta) {
  respuesta = matchRespuesta[0].replace(/^RESPUESTA:\s*/i, '').trim();
} else {
  respuesta = geminiText.trim();
}

if (!respuesta) {
  respuesta = 'Hola ' + nombre + ', gracias por contactarnos. 😊\n\nHemos recibido tu reporte. Para ayudarte mejor, ¿podrías indicarnos?\n\n1️⃣ ¿Desde cuándo presenta esa falla?\n2️⃣ ¿Ocurre todo el tiempo o solo en ciertas condiciones?\n3️⃣ ¿Qué modelo y año es tu moto?\n\nTambién puedes pasar al taller para una revisión gratuita. 🔧';
} else {
  respuesta += '\n\n🔧 *Moto Servicios TIMON*\n📍 Calle Principal #123, Col. Centro\n📞 Tel: 123-456-7890\n🕐 Lun-Vie: 9AM-6PM, Sáb: 9AM-2PM\n\n¿Te gustaría agendar una revisión?';
}

return [{
  json: {
    telefono: telefono,
    mensaje: mensaje,
    respuesta: respuesta,
    categoria: 'DIAGNOSTICO'
  }
}];
